module.exports = {
  rootDir: "/luxon",
  testEnvironment: "node",
  roots: ["tmp-verify"]
};
import { DateTime } from "../src/luxon.js";

test("plus across 100 barrier", () => {
  const d = DateTime.fromISO("0099-12-31").plus({ day: 2 });
  console.log("plus:", d.year, d.month, d.day, d.toISO());
  expect([d.year, d.month, d.day]).toEqual([100, 1, 2]);
});

test("minus across 100 barrier", () => {
  const d = DateTime.fromISO("0100-01-02").minus({ day: 2 });
  console.log("minus:", d.year, d.month, d.day, d.toISO());
  expect([d.year, d.month, d.day]).toEqual([99, 12, 31]);
});
import { DateTime } from "../src/luxon.js";

function refPlusDays(iso, days) {
  const [y, m, d] = iso.split("-").map(Number);
  const base = new Date(Date.UTC(2000, m - 1, d));
  base.setUTCFullYear(y);
  const ts = base.getTime() + days * 86400000;
  const dd = new Date(ts);
  return [dd.getUTCFullYear(), dd.getUTCMonth() + 1, dd.getUTCDate()];
}

test("brute days across 100", () => {
  const bad = [];
