/* global test expect */
import { Interval, Settings } from "../src/luxon";

const withThrowOnInvalid = (value, f) => {
  const existing = Settings.throwOnInvalid;
  try {
    Settings.throwOnInvalid = value;
    f();
  } finally {
    Settings.throwOnInvalid = existing;
  }
};

test("Interval.fromISO works with Settings.throwOnInvalid", () => {
  withThrowOnInvalid(true, () => {
    expect(() => Interval.fromISO("2016-01-01/2016-12-31")).not.toThrow();
    expect(() => Interval.fromISO("2016-01-01/P1Y")).not.toThrow();
    expect(() => Interval.fromISO("P1Y/2016-01-01")).not.toThrow();
    expect(() => Interval.fromISO("bad")).toThrow();
    expect(() => Interval.fromISO("2016-01-01/bad")).toThrow();
    expect(() => Interval.fromISO("bad/2016-01-01")).toThrow();
  });
});

test("Interval.fromISO returns invalid intervals when throwOnInvalid is false", () => {
  withThrowOnInvalid(false, () => {
    for (const s of ["bad", "2016-01-01/bad", "bad/2016-01-01", "foo/bar"]) {
      const i = Interval.fromISO(s);
      expect(i.isValid).toBe(false);
      expect(i.invalidReason).toBe("unparsable");
    }
    // duration forms still parse
    expect(Interval.fromISO("2016-01-01/P1Y").isValid).toBe(true);
    expect(Interval.fromISO("P1Y/2016-01-01").isValid).toBe(true);
  });
});
