  const bad = [];
  for (let startMonth = 1; startMonth <= 12; startMonth++) {
    for (let startDay = 1; startDay <= 28; startDay++) {
      const iso = `0099-${String(startMonth).padStart(2, "0")}-${String(startDay).padStart(2, "0")}`;
      for (let n = 0; n <= 120; n++) {
        const d = DateTime.fromISO(iso).plus({ days: n });
        const got = [d.year, d.month, d.day];
        const exp = refPlusDays(iso, n);
